Notification[] channels = [new EmailNotification(), new SmsNotification()];
foreach (var channel in channels) channel.Send();
abstract class Notification { public abstract void Send(); }
class EmailNotification : Notification { public override void Send() => Console.WriteLine("Email"); }
class SmsNotification : Notification { public override void Send() => Console.WriteLine("SMS"); }

